// Synthetic API fixtures for the real React router; no backend or database access.
const departure='2027-01-15T15:30:00Z',arrival='2027-01-15T22:30:00Z';
const pickup={tripStopId:11,locationId:1,name:'Bến xe Thành phố Hồ Chí Minh',departureTime:departure,time:departure};
const dropoff={tripStopId:12,locationId:2,name:'Bến xe Đà Lạt',arrivalTime:arrival,time:arrival};
const seats=Array.from({length:16},(_,i)=>({tripSeatId:i+1,seatCode:'A'+String(i+1).padStart(2,'0'),row:Math.floor(i%8/2)+1,column:i%2?3:1,floor:i<8?1:2,seatType:'STANDARD',available:i!==7}));
const trip={tripId:7,operator:{id:1,name:'Nhà xe thử nghiệm Hành Trình Việt'},route:{id:1,name:'Thành phố Hồ Chí Minh – Đà Lạt'},busType:{id:1,name:'Giường nằm hai tầng'},busImageUrl:null,pickup,dropoff,durationMinutes:420,price:350000,availableSeats:15,status:'SCHEDULED',stops:[{...pickup,stopOrder:1,arrivalTime:null,allowPickup:true,allowDropoff:false},{...dropoff,stopOrder:2,departureTime:null,allowPickup:false,allowDropoff:true}]};
const opTrip={id:7,status:'SCHEDULED',route:trip.route,bus:{id:2,licensePlate:'51B-TEST',busTypeName:trip.busType.name},departureTime:departure,estimatedArrivalTime:arrival,seatCount:16,segmentCount:1,seats:seats.map(s=>({...s,id:s.tripSeatId})),stops:[{id:11,stopOrder:1,locationId:1,locationName:pickup.name},{id:12,stopOrder:2,locationId:2,locationName:dropoff.name}],segments:[{id:90,segmentOrder:1,fromTripStopId:11,toTripStopId:12}]};
const booking={bookingId:101,bookingCode:'BG-TEST-101',status:'CONFIRMED',tripId:7,trip:opTrip,route:trip.route,operator:trip.operator,pickup,dropoff,contact:{name:'Khách thử nghiệm',phone:'0900000000',email:'fixture@example.invalid'},seatCount:2,paymentStatus:'PAID',totalAmount:700000,createdAt:departure};
const ticket={id:2,subject:'Kiểm tra thông tin đặt vé · Dữ liệu thử nghiệm',category:'BOOKING_HELP',status:'IN_PROGRESS',priority:'NORMAL',bookingCode:'BG-TEST-101',operatorName:trip.operator.name,escalation:'PLATFORM',disputeStatus:'UNDER_REVIEW',updatedAt:departure,assignedUserId:null};
const page=data=>({data,pagination:{page:0,size:20,totalElements:data.length,totalPages:1}});
const totals=Object.fromEntries(['collections','refunds','netCollections','commissionAccrual','commissionReversal','netCommission','operatorPayable','platformReceivable','unknownAmount','unpricedAmount','grossContext','discountContext','eventCount','sourceCount','missingCount','sourceCollections','sourceRefunds','unknownCount','unpricedCount'].map(k=>[k,0]));
const dataFor=(path,role)=>{
 if(path==='/users/me')return {data:{id:1,fullName:'Nguyễn Minh Anh · Thử nghiệm',email:'fixture@example.invalid',phone:'0900000000',roles:[role]}};
 if(path.endsWith('/unread-count'))return {data:0};
 if(path.endsWith('/notifications'))return page([]);
 if(path==='/trips/7')return {data:trip};
 if(path==='/trips/7/seats')return {data:{tripId:7,pickup,dropoff,price:350000,availableSeatCount:15,seats}};
 if(path==='/trips/7/live')return {data:{tripId:7,status:'SCHEDULED',delayMinutes:0,stops:[]}};
 if(path==='/bookings/me')return page([{...booking,routeName:trip.route.name,operatorName:trip.operator.name,departureTime:departure,seats:['A01','A02']}]);
 if(path==='/operator/trips')return page([opTrip]);
 if(path==='/operator/trips/7')return {data:opTrip};
 if(path==='/operator/bookings')return page([booking,{...booking,bookingId:102,bookingCode:'BG-TEST-102',status:'PENDING',paymentStatus:'PENDING'}]);
 if(path==='/operator/trips/7/occupancy')return {data:{tripId:7,tripStatus:'SCHEDULED',seatCount:16,segmentCount:1,wholeTripAvailableSeatCount:12,complete:true,expectedInventoryCellCount:16,actualInventoryCellCount:16,missingInventoryCellCount:0,segments:[{tripSegmentId:90,segmentOrder:1,fromTripStopId:11,toTripStopId:12,fromName:pickup.name,toName:dropoff.name,counts:{available:12,held:1,booked:2,blocked:1}}],seats:seats.map((s,i)=>({...s,segments:[{tripSegmentId:90,segmentOrder:1,status:i<2?'BOOKED':i===2?'HELD':i===3?'BLOCKED':'AVAILABLE',missing:false,bookingId:i<2?101:null,bookingCode:i<2?booking.bookingCode:null}]}))}};
 if(path==='/operator/reports/summary')return {data:{operations:{upcomingWithoutDriver:1,openPickups:2,incompleteTrips:0},attendance:{unresolvedAttendance:2},bookings:{bookingsCreated:2,validTickets:2,currentUnpaidCount:1},collections:{totals:{grossMockCollections:700000,mockRefunds:0}},metadata:{asOf:departure}}};
 if(path==='/operator/fleet/readiness')return {data:{availableBuses:2,maintenanceBuses:0,inactiveBuses:0,maintenanceDueSoon:0,overdueMaintenance:0,upcomingNotReady:[]}};
 if(path.endsWith('/finance/overview'))return {data:{period:{from:'2026-10-01',to:'2026-10-22'},operatorName:trip.operator.name,reconciliationStatus:'NOT_RECONCILED',totals:{...totals,sourceCollections:650000,sourceCount:1,missingCount:1}}};
 if(path.endsWith('/finance/ledger'))return {data:{data:[],page:0,size:20,total:0}};
 if(path.endsWith('/finance/operators'))return {data:{data:[{id:1,name:trip.operator.name}],page:0,size:20,total:1}};
 if(path==='/admin/dashboard')return {data:{SUBMITTED:3,ACTIVE:5,SUSPENDED:1}};
 if(path==='/admin/operator-applications')return page([]);
 if(path==='/admin/operators')return page([]);
 if(path.endsWith('/tickets'))return page([ticket]);
 if(path.endsWith('/dashboard'))return {data:[{key:'OPEN',count:1},{key:'IN_PROGRESS',count:1}]};
 if(path.endsWith('/audit-events'))return page([]);
 if(path==='/public/discovery/operators'||path==='/public/reviews/recent')return page([]);
 if(path==='/public/discovery/routes'||path==='/public/discovery/trips')return {data:[]};
 if(path==='/locations')return {data:[{id:1,name:pickup.name,province:'TP. Hồ Chí Minh'},{id:2,name:dropoff.name,province:'Lâm Đồng'}]};
 if(path==='/operators'||path==='/bus-types')return {data:[]};
 return undefined;
};
module.exports={dataFor};
